{"command":"cat > src/configuration.py <<'PY'
"""Configuration parsing and persistence for the terminal client."""
import os
import re
import json
import copy
import ast
import sys
from pathlib import Path


def resource(name):
    try:
        return Path(__file__).with_name(name).read_text()
    except (OSError, NotADirectoryError):
        import zipfile
        with zipfile.ZipFile(sys.argv[0]) as archive:
            return archive.read(name).decode()


class YamlError(ValueError):
    pass


def split_inline(text, sep=','):
    result, start, quote, depth = [], 0, None, 0
    i = 0
    while i < len(text):
        c = text[i]
        if quote:
            if c == quote and (i == 0 or text[i-1] != '\\'):
                if quote == "'" and i+1 < len(text) and text[i+1] == "'":
                    i += 1
                else:
                    quote = None
        elif c in "\"'":
            quote = c
        elif c in '[{(':
            depth += 1
        elif c in ']})':
            depth -= 1
        elif c == sep and not depth:
            result.append(text[start:i].strip()); start = i + 1
        i += 1
    result.append(text[start:].strip())
    return result


def scalar(value, line=1):
    value = value.strip()
    if not value or value in ('null', 'Null', 'NULL', '~'):
        return None
    if value.startswith("'"):
        if not value.endswith("'") or len(value) < 2:
            raise YamlError(f'yaml: line {line}: found unexpected end of stream')
        return value[1:-1].replace("''", "'")
    if value.startswith('"'):
        try:
            return json.loads(value)
        except ValueError:
            try:
                return ast.literal_eval(value)
            except Exception:
                raise YamlError(f'yaml: line {line}: found unexpected end of stream')
    if value.startswith('['):
        if not value.endswith(']'):
            raise YamlError(f'yaml: line {line}: did not find expected node content')
        return [scalar(v, line) for v in split_inline(value[1:-1]) if v]
    if value.startswith('{'):
        if not value.endswith('}'):
            raise YamlError(f'yaml: line {line}: did not find expected node content')
        obj = {}
        for item in split_inline(value[1:-1]):
            if not item: continue
            key, sep, val = item.partition(':')
            obj[str(scalar(key, line))] = scalar(val, line) if sep else None
        return obj
    value = re.split(r'\s+#', value, maxsplit=1)[0].rstrip()
    if value.lower() in ('true', 'false'):
        return value.lower() == 'true'
    if re.fullmatch(r'[-+]?\d+', value):
        try: return int(value)
        except ValueError: pass
    if re.fullmatch(r'[-+]?(?:\d+\.\d*|\.\d+)(?:[eE][-+]?\d+)?', value):
        return float(value)
    return value


def yaml_load(text):
    if text.lstrip().startswith('{'):
        try: return json.loads(text)
        except ValueError: pass
    lines = []
    for n, raw in enumerate(text.splitlines(), 1):
        if '\t' in raw[:len(raw)-len(raw.lstrip())]:
            raise YamlError(f'yaml: line {n}: found character that cannot start any token')
        if not raw.strip() or raw.lstrip().startswith('#') or raw.strip() in ('---','...'):
            continue
        lines.append((len(raw)-len(raw.lstrip()), raw.lstrip(), n, raw))
    if not lines: return {}
    if len(lines) == 1 and ':' not in lines[0][1] and not lines[0][1].startswith('- '):
        return scalar(lines[0][1], lines[0][2])

    def keyval(s, n):
        quote = None
        for i, c in enumerate(s):
            if quote:
                if c == quote and (i == 0 or s[i-1] != '\\'): quote = None
            elif c in "\"'": quote = c
            elif c == ':' and (i+1 == len(s) or s[i+1].isspace()):
                key = s[:i].strip()
                if key[:1] in "\"'": key = scalar(key, n)
                return str(key), s[i+1:].strip()
        raise YamlError(f'yaml: line {n}: could not find expected \':\'')

    def block(i, indent):
        seq = lines[i][1] == '-' or lines[i][1].startswith('- ')
        result = [] if seq else {}
        while i < len(lines) and lines[i][0] == indent:
            _, content, number, _ = lines[i]
            if seq:
                if not (content == '-' or content.startswith('- ')): break
                rest = content[1:].strip()
                i += 1
                if not rest:
                    if i < len(lines) and lines[i][0] > indent:
                        val, i = block(i, lines[i][0])
                    else: val = None
                    result.append(val)
                elif re.search(r':(?:\s|$)', rest) and rest[:1] not in '[{\"\'':
                    key, val = keyval(rest, number)
                    obj = {}
                    if val:
                        obj[key] = scalar(val, number)
                    elif i < len(lines) and lines[i][0] > indent+2:
                        obj[key], i = block(i, lines[i][0])
                    else: obj[key] = None
                    if i < len(lines) and lines[i][0] > indent:
                        additional, i = block(i, lines[i][0])
                        if isinstance(additional, dict): obj.update(additional)
                    result.append(obj)
                else:
                    result.append(scalar(rest, number))
            else:
                if content.startswith('- '): break
                key, val = keyval(content, number)
                i += 1
                if val in ('|','|-','|+','>','>-','>+'):
                    chunks = []
                    base = lines[i][0] if i < len(lines) and lines[i][0] > indent else indent+2
                    while i < len(lines) and lines[i][0] > indent:
                        chunks.append(lines[i][3][base:]); i += 1
                    result[key] = (' ' if val.startswith('>') else '\n').join(chunks) + ('' if val.endswith('-') else '\n')
                elif val:
                    result[key] = scalar(val, number)
                elif i < len(lines) and (lines[i][0] > indent or (lines[i][0] == indent and lines[i][1].startswith('- '))):
                    result[key], i = block(i, lines[i][0])
                else:
                    result[key] = None
        return result, i
    parsed, at = block(0, lines[0][0])
    if at < len(lines):
        raise YamlError(f'yaml: line {lines[at][2]}: did not find expected key')
    return parsed


def deep_merge(base, patch):
    for key, value in patch.items():
        if value is None: continue
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            deep_merge(base[key], value)
        else: base[key] = copy.deepcopy(value)
    return base


def default_config_dir():
    home = os.path.expanduser('~')
    root = os.environ.get('XDG_CONFIG_HOME', '')
    if not os.path.isabs(root): root = os.path.join(home, '.config')
    old = os.path.join(root, 'jesseduffield', 'lazygit')
    if os.path.isdir(old): return old
    return os.path.join(root, 'lazygit')


def state_root(config_dir, overridden=False):
    if overridden: return config_dir
    root = os.environ.get('XDG_STATE_HOME', '')
    if not os.path.isabs(root): root = os.path.join(os.path.expanduser('~'), '.local', 'state')
    return os.path.join(root, 'lazygit')


class Config:
    def __init__(self, directory, files=None, override_dir=False):
        self.directory = directory
        self.state_directory = state_root(directory, override_dir)
        self.data = yaml_load(resource('default-config.yml'))
        self.files = files.split(',') if files is not None and files != '' else [os.path.join(directory, 'config.yml')]
        self.state_path = os.path.join(self.state_directory, 'state.yml')
        self.state = {
            'lastupdatecheck': 0, 'recentrepos': [], 'startuppopupversion': 0,
            'didshowhunkstaginghint': False, 'lastversion': '',
            'customcommandshistory': [], 'hidecommandlog': False,
        }
        for p in [self.state_path, os.path.join(directory, 'state.yml')]:
            try:
                st = yaml_load(Path(p).read_text())
                if isinstance(st, dict): self.state.update(st)
                break
            except (OSError, ValueError): pass
        self.explicit_files = bool(files)

    def get(self, key, default=None):
        value = self.data
        for part in key.split('.'):
            if not isinstance(value, dict): return default
            value = value.get(part, default)
        return value

    def load(self):
        try: os.makedirs(self.directory, exist_ok=True)
        except OSError as e:
            if os.path.isfile(self.directory): raise ValueError(f'mkdir {self.directory}: not a directory')
            raise ValueError(f'mkdir {self.directory}: permission denied')
        for p in self.files:
            if not os.path.exists(p):
                if self.explicit_files: raise ValueError(f'stat {p}: no such file or directory')
                try: Path(p).write_text('')
                except OSError: raise ValueError(f'open {p}: permission denied')
            self.read(p)

    def read(self, path):
        try: text = Path(path).read_text()
        except IsADirectoryError: raise ValueError(f'read {path}: is a directory')
        except OSError: raise ValueError(f'open {path}: permission denied')
        try: data = yaml_load(text)
        except YamlError as e: raise ValueError('failed to parse YAML: '+str(e))
        if not isinstance(data, dict):
            raise ValueError(f"Couldn't migrate config file at `{path}` for key gui.skipUnstageLineWarning: yaml node in path is not a dictionary")
        failures = []
        def validate(patch, base, prefix=''):
            for key, v in patch.items():
                expect = base.get(key) if isinstance(base, dict) else None
                if isinstance(v, dict) and isinstance(expect, dict): validate(v, expect, prefix+key+'.')
                elif expect is not None and v is not None:
                    typ = 'bool' if isinstance(expect, bool) else 'int' if isinstance(expect, int) else 'float64' if isinstance(expect, float) else ''
                    bad = (typ == 'bool' and not isinstance(v, bool)) or (typ in ('int','float64') and not isinstance(v, (int,float)))
                    if typ == 'bool' and str(v).lower() in ('yes','no','on','off'):
                        patch[key] = str(v).lower() in ('yes','on'); bad = False
                    if bad:
                        lineno = next((i+1 for i,l in enumerate(text.splitlines()) if re.match(r'\s*'+re.escape(key)+r'\s*:', l)),1)
                        tag = 'str' if isinstance(v,str) else 'seq' if isinstance(v,list) else 'map' if isinstance(v,dict) else 'bool'
                        failures.append(f'  line {lineno}: cannot unmarshal !!{tag} `{str(v)[:16]}` into {typ}')
        validate(data, self.data)
        if failures:
            raise ValueError(f"The config at `{path}` couldn't be parsed, please inspect it before opening up an issue.\nyaml: unmarshal errors:\n"+'\n'.join(failures))
        keys = data.get('keybinding') or {}
        for context, mappings in keys.items():
            if not isinstance(mappings,dict): continue
            for action, binding in mappings.items():
                for b in binding if isinstance(binding,list) else [binding]:
                    b = str(b)
                    if len(b) != 1 and not re.fullmatch(r'<(?:(?:c|a)-.|s-(?:up|down)|f\d\d?|space|disabled|esc|enter|backspace|delete|insert|tab|backtab|up|down|left|right|home|end|pgup|pgdown)>',b):
                        nm = context[0].upper()+context[1:]+'.'+''.join(x[:1].upper()+x[1:] for x in action.split('-'))
                        raise ValueError(f"The config at `{path}` has a validation error.\nUnrecognized key '{b}' for keybinding '{nm}'. For permitted values see https://github.com/jesseduffield/lazygit/blob/master/docs/keybindings/Custom_Keybindings.md")
        deep_merge(self.data,data)

    def load_repo(self, repo, gitdir):
        parents = list(Path(repo).parents)[::-1] + [Path(repo)]
        for d in parents:
            p = d / '.lazygit.yml'
            if p.is_file(): self.read(str(p))
        p = Path(gitdir) / 'lazygit.yml'
        if p.is_file(): self.read(str(p))

    def save_state(self):
        try:
            os.makedirs(self.state_directory,exist_ok=True)
            def fmt(v):
                if v is True: return 'true'
                if v is False: return 'false'
                if v is None: return 'null'
                if v == '': return '""'
