"""Small, self-contained cell terminal renderer and keyboard decoder."""
import os
import re
import time
import select
import signal
import termios
import tty
import unicodedata

ANSI = re.compile(r'\x1b\[([0-9;]*)m|\x1b\][^\x07]*(?:\x07|\x1b\\)|\x1b\[[0-9;?]*[A-Za-z]')


def strip_ansi(s):
    return ANSI.sub('',str(s))


def cell_width(c):
    if unicodedata.combining(c): return 0
    if ord(c) < 32 or ord(c) == 127: return 0
    return 2 if unicodedata.east_asian_width(c) in ('W','F') else 1


def width(text):
    return sum(cell_width(c) for c in strip_ansi(text))


def truncate(text,n):
    result = ''; used=0
    for c in strip_ansi(text):
        k=cell_width(c)
        if used+k > n: break
        result+=c; used+=k
    return result


def wrap(text,w):
    if w <= 0: return ['']
    out=[]
    for line in str(text).split('\n'):
        if not line: out.append(''); continue
        while width(line)>w:
            part=truncate(line,w)
            space=part.rfind(' ')
            if space>0:
                out.append(part[:space]); line=line[space+1:]
            else:
                out.append(part); line=line[len(part):]
        out.append(line)
    return out


def color(values, default='0'):
    if not isinstance(values,list): return default
    codes=[]
    names={'default':39,'black':30,'red':31,'green':32,'yellow':33,'blue':34,'magenta':35,'cyan':36,'white':37,'bold':1,'underline':4,'reverse':7,'dim':2,'italic':3,'strikethrough':9}
    for value in values:
        value=str(value)
        if value in names: codes.append(str(names[value]))
        elif re.fullmatch(r'#[0-9a-fA-F]{6}',value):
            codes.append('38;2;'+ ';'.join(str(int(value[i:i+2],16)) for i in (1,3,5)))
        elif value.isdigit(): codes.append('38;5;'+value)
    return ';'.join(codes) if codes else default


class Canvas:
    def __init__(self,w,h):
        self.w,self.h=w,h
        self.rows = [[(' ','0') for _ in range(w)] for _ in range(h)]
        self.cursor = None

    def put(self,x,y,text,style='0',limit=None):
        if y < 0 or y >= self.h: return
        x=int(x); y=int(y)
        maxx = min(self.w, x+limit) if limit is not None else self.w
        s = str(text).replace('\r','').expandtabs(4)
