        if key=='<enter>':
            self.search_edit=False;self.search_active=bool(self.search_text);self.search_match=0
            matches=self.search_matches()
            if matches and not self.is_filter(self.search_context):self.positions[self.search_context]=matches[0];self.main_scroll=[0,0]
        else:
