    def mouse_key(self,key):
        _,button,x,y,down=key
        if button in (64,65):
            self.handle_key('<up>' if button==64 else '<down>');return
        if not down:return
        if self.popup:return
        for panel,rect in self.rects.items():
            rx,ry,rw,rh=rect
            if rx<=x<rx+rw and ry<=y<ry+rh:
                if isinstance(panel,int):
                    self.set_focus(panel);c=self.ctx()
                    if y>ry:self.positions[c]=min(max(0,y-ry-1+self.list_scroll.get(c,0)),max(0,len(self.items())-1));self.main_cache={}
                elif panel=='main':self.set_focus(0)
                elif panel=='log':self.focus_log()
                break

    def execute(self,args,label='',input=None,env=None,record=True,show_output=False):
        oldhead=self.git.head
        if label:self.command_log.append(label)
        if isinstance(args,str):display=args;is_shell=True
        else:
            is_shell=False
            def quoted(a):
                if re.fullmatch(r'[A-Za-z0-9_./:@{}=+%-]+',a):return a
                return json.dumps(a,ensure_ascii=False)
            display='git '+' '.join(quoted(str(a)) for a in args)
        self.command_log.append('  '+display)
        result=self.git.run(args,input=input,env=env,shell=is_shell)
        if record and oldhead:self.undo_stack.append((oldhead,self.git.branch,args));self.redo_stack=[]
        if show_output and result.stdout.strip():self.command_log.extend(['','Git output:']+result.stdout.rstrip().splitlines())
        self.refresh()
        if result.returncode:
            self.error((result.stderr or result.stdout).strip())
        return result

    def files_key(self,key):
        item=self.selected('files')
