        elif key=='`':
            self.tree_mode=not self.tree_mode;self.positions['files']=0;self.refresh()
        elif key in ('-','='):
            self.collapsed=set(e['name'] for e in self.file_entries if e.get('directory')) if key=='-' else set();self.refresh()
        elif key=='<enter>' and item:
            if item.get('directory'):
