                if name in self.collapsed:self.collapsed.remove(name)
                else:self.collapsed.add(name)
                self.refresh()
            else:self.enter_staging(item)
        elif key in ('e','o') and item:self.external_editor(item['name']) if key=='e' else self.open_file(item['name'])
        elif key=='<c-b>':self.file_filter_menu()
