        elif key=='y':self.menu('Copy to clipboard',[('','Path',lambda:self.copy_text(item['name'] if item else '')),('','Absolute path',lambda:self.copy_text(os.path.join(self.git.path,item['name']) if item else '')),('','Cancel',None)])
        elif key=='M':self.conflict_menu(item)
