    def toggle_stage(self,item,all_files=False):
        if not self.git.files:return
        if all_files or (item and item.get('name')=='.'):
            staged=not any(f['unstaged'] for f in self.git.files)
            if staged:
                args=['reset'] if self.git.head else ['rm','--cached','-r','.']
                self.execute(args,'Unstage all files',record=False)
            else:self.execute(['add','-A'],'Stage all files',record=False)
            return
        if not item:return
        files=[item]
        if self.range_start is not None:
            p=self.positions.get('files',0);files=self.file_entries[min(p,self.range_start):max(p,self.range_start)+1]
        paths=[i['name'] for i in files]
        stage=any(i.get('unstaged') for i in files)
        if stage:args=['add','--']+paths
        else:args=(['reset','HEAD','--'] if self.git.head else ['rm','--cached','--'])+paths
        self.execute(args,'Stage file' if stage else 'Unstage file',record=False)

    def begin_commit(self,nohook=False,editor=False):
        if not any(f['staged'] for f in self.git.files):
            if self.cfg.get('gui.skipNoStagedFilesWarning',False):
                self.toggle_stage(None,True);self.open_commit(nohook=nohook,editor=editor)
            else:
                def all_then_commit():self.toggle_stage(None,True);self.open_commit(nohook=nohook,editor=editor)
                self.confirm('No files staged','You have not staged any files. Commit all files?',all_then_commit)
        else:self.open_commit(nohook=nohook,editor=editor)

    def open_commit(self,initial='',description='',callback=None,title='Commit summary',nohook=False,editor=False):
        from interface import Popup
        if editor:
            self.external_command('git commit'+(' --no-verify' if nohook else ''));return
        if not callback:
            def commit(summary,body):
                msg=summary+('\n\n'+body if body else '')
                args=['commit','-m',msg]
                if nohook:args+=['--no-verify']
                if self.cfg.get('git.commit.signOff'):args+=['--signoff']
                result=self.execute(args,'Commit',show_output=True)
                if result.returncode==0:self.saved_commit=('', '')
            callback=commit
            if not initial:
                initial,description=getattr(self,'saved_commit',('',''))
        self.popup=Popup('commit',title,initial,callback,cursor=len(initial),description=description,desc_cursor=len(description))

