    def discard_menu(self,item):
        name=item['name']
        def discard(all_changes):
            def perform():
                if item.get('untracked'):
                    path=Path(self.git.path)/name
                    try:
                        if path.is_dir():
                            import shutil;shutil.rmtree(path)
                        else:path.unlink()
                    except OSError as e:self.error(str(e))
                    self.command_log.extend(['Discard changes','  rm '+shlex.quote(name)]);self.refresh()
                elif all_changes:
                    if item.get('staged') and item.get('status','')[0]=='A':
                        self.execute(['rm','--force','--',name],'Discard changes',record=False)
                    else:
                        self.execute(['reset','HEAD','--',name],'Unstage file',record=False)
