                else:self.execute(['checkout','--',name],'Discard unstaged changes',record=False)
            self.confirm('Discard changes',"Are you sure you want to discard changes to '"+name+"'?",perform)
        self.menu('Discard changes',[
            ('x','Discard all changes',lambda:discard(True),"Discard both staged and unstaged changes in '"+name+"'."),
            ('u','Discard unstaged changes',lambda:discard(False),"Discard unstaged changes in '"+name+"'."),('','Cancel',None)])

    def ignore_menu(self,item):
