            else:perform()
        self.menu('Ignore or exclude file',[('i','Add to .gitignore',lambda:add('.gitignore')),('e','Add to .git/info/exclude',lambda:add(os.path.join(self.git.gitdir,'info','exclude'))),('','Cancel',None)])

