    def stage_move(self,key):
        data=self.main_data();lines=strip_ansi(data[min(self.stage_side,len(data)-1)][1]).splitlines()
        if key in ('<','<home>'):self.stage_line=0
        elif key in ('>','<end>'):self.stage_line=max(0,len(lines)-1)
        elif self.hunk_mode:
            indices=[i for i,l in enumerate(lines) if l.startswith('@@')]
            if key in ('j','<down>','<s-down>','.'):
                self.stage_line=next((i for i in indices if i>self.stage_line),self.stage_line)
            else:self.stage_line=next((i for i in reversed(indices) if i<self.stage_line),self.stage_line)
        else:
            self.stage_line=min(max(0,self.stage_line+(-1 if key in ('k','<up>','<s-up>',',') else 1)),max(0,len(lines)-1))
        i=self.stage_side
        vh=self.main_rects[min(i,len(self.main_rects)-1)][3]-2 if hasattr(self,'main_rects') else 10
        if self.stage_line<self.main_scroll[i]:self.main_scroll[i]=self.stage_line
        if self.stage_line>=self.main_scroll[i]+vh:self.main_scroll[i]=self.stage_line-vh+1

    def staging_key(self,key):
        item=self.selected('files')
        if key=='a':self.hunk_mode=not self.hunk_mode;return
        if key in ('<space>','d'):
            if key=='d' and not self.cfg.get('gui.skipDiscardChangeWarning',False):
                self.confirm('Discard changes','Are you sure you want to discard the selected changes?',lambda:self.apply_selected_patch(True))
            else:self.apply_selected_patch(key=='d')
        elif key=='<enter>':self.apply_selected_patch(False)
        elif key=='e' and item:self.external_editor(item['name'])

    def apply_selected_patch(self,discard=False):
        item=self.selected('files')
        if not item:return
        text=strip_ansi(self.git.diff(item,self.stage_side==1))
        lines=text.splitlines(True)
        starts=[i for i,l in enumerate(lines) if l.startswith('@@')]
        if not starts:return
        start=max([i for i in starts if i<=self.stage_line] or [starts[0]])
        end=next((i for i in starts if i>start),len(lines))
        chunk=lines[start:end]
        if not self.hunk_mode:
            chosen=self.stage_line
            rebuilt=[];oldcount=0;newcount=0
            for index,l in enumerate(chunk[1:],start+1):
                if l.startswith('\\'):continue
                if l.startswith('+'):
                    if index==chosen:rebuilt.append(l);newcount+=1
                elif l.startswith('-'):
                    if index==chosen:rebuilt.append(l);oldcount+=1
                    else:rebuilt.append(' '+l[1:]);oldcount+=1;newcount+=1
                else:rebuilt.append(l);oldcount+=1;newcount+=1
            m=re.match(r'@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)',chunk[0])
            if m:chunk=[f'@@ -{m[1]},{oldcount} +{m[2]},{newcount} @@{m[3]}\n']+rebuilt
        patch=''.join(lines[:starts[0]]+chunk)
        args=['apply','--unidiff-zero','--recount']
        if not discard:args+=['--cached']
        if self.stage_side==1 or discard:args+=['--reverse']
        result=self.execute(args,'Discard changes' if discard else ('Unstage hunk' if self.stage_side==1 else 'Stage hunk'),input=patch,record=False)
        if result.returncode and self.hunk_mode:
            self.popup=None;self.toggle_stage(item)
        self.main_scroll=[0,0];self.stage_line=0

