    def run_custom(self,command):
        form={};responses=[]
        def template(text):return self.template(str(text),form,responses)
        prompts=command.get('prompts') or []
        def advance(index):
            if index>=len(prompts):
                cmd=template(command.get('command',''))
                if command.get('output')=='terminal':self.external_command(cmd);return
                self.command_log.append('  '+cmd)
                p=self.git.run(cmd,shell=True)
                self.refresh()
                if command.get('output')=='popup':self.error(p.stdout+p.stderr,template(command.get('outputTitle') or cmd))
                elif p.returncode:self.error(p.stderr or p.stdout)
                elif command.get('output') in ('log','logWithPty'):self.command_log.extend(p.stdout.rstrip().splitlines())
                return
            prompt=prompts[index];kind=prompt.get('type','input')
            def accept(value=''):
                responses.append(value)
                if prompt.get('key'):form[prompt['key']]=value
                advance(index+1)
            if kind=='input':self.prompt(template(prompt.get('title','')),accept,template(prompt.get('initialValue','')))
            elif kind=='confirm':self.confirm(template(prompt.get('title','')),template(prompt.get('body','')),lambda:accept(''))
            elif kind in ('menu','menuFromCommand','menu-from-command'):
                opts=[]
                for option in prompt.get('options',[]):
                    v=template(option.get('value',option.get('name','')))
                    label=template(option.get('name',v))
                    if option.get('description'):label+=' '+template(option['description'])
                    opts.append(('',label,lambda value=v:accept(value)))
                if not opts and prompt.get('command'):
                    out=self.git.run(template(prompt['command']),shell=True).stdout
                    regex=prompt.get('filter')
                    for l in out.splitlines():
                        val=l
                        if regex:
                            m=re.search(regex,l)
                            if not m:continue
                            val=m.group(1) if m.groups() else m.group(0)
                        opts.append(('',l,lambda v=val:accept(v)))
                self.menu(template(prompt.get('title','')),opts+[('','Cancel',None)])
            else:advance(index+1)
        advance(0)

    def template(self,text,form,responses):
        selected_file=self.selected('files') or {};branch=self.selected('localBranches') or {};commit=self.selected('commits') or {};stash=self.selected('stash') or {}
        values={'.SelectedFile.Name':selected_file.get('name',''),'.SelectedFile.Path':selected_file.get('name',''),
                '.SelectedFile.HasUnstagedChanges':selected_file.get('unstaged',False),'.SelectedFile.HasStagedChanges':selected_file.get('staged',False),
                '.SelectedLocalBranch.Name':branch.get('name',''),'.SelectedRemoteBranch.Name':(self.selected('remoteBranches') or {}).get('name',''),
                '.SelectedLocalCommit.Hash':commit.get('hash',''),'.SelectedCommit.Hash':commit.get('hash',''),'.SelectedLocalCommit.Name':commit.get('message',''),
                '.CheckedOutBranch.Name':self.git.branch,'.SelectedStashEntry.RefName':stash.get('ref',''),'.SelectedStashEntry.Name':stash.get('name',''),
                '.SelectedTag.Name':(self.selected('tags') or {}).get('name',''),'.SelectedRemote.Name':(self.selected('remotes') or {}).get('name',''),
                '.RepoPath':self.git.path,'.GitDir':self.git.gitdir}
        def val(expression):
            expr=expression.strip()
            if expr.startswith('.Form.'):return form.get(expr[6:],'')
            m=re.match(r'index\s+\.PromptResponses\s+(\d+)',expr)
            if m:return responses[int(m[1])] if int(m[1])<len(responses) else ''
            return values.get(expr,expr.strip('"'))
        def conditional(m):
            body=m[2].split('{{else}}',1)
            return body[0] if val(m[1]) else (body[1] if len(body)>1 else '')
        text=re.sub(r'{{\s*if\s+(.*?)\s*}}(.*?){{\s*end\s*}}',conditional,text,flags=re.S)
        def replace(m):
