    def stage_move(self,key):
        data=self.main_data();lines=strip_ansi(data[min(self.stage_side,len(data)-1)][1]).splitlines()
        if key in ('<','<home>'):self.stage_line=0
        elif key in ('>','<end>'):self.stage_line=max(0,len(lines)-1)
        elif self.hunk_mode:
            indices=[i for i,l in enumerate(lines) if l.startswith('@@')]
            if key in ('j','<down>','<s-down>','.'):
                self.stage_line=next((i for i in indices if i>self.stage_line),self.stage_line)
            else:self.stage_line=next((i for i in reversed(indices) if i<self.stage_line),self.stage_line)
        else:
            self.stage_line=min(max(0,self.stage_line+(-1 if key in ('k','<up>','<s-up>',',') else 1)),max(0,len(lines)-1))
        i=self.stage_side
        vh=self.main_rects[min(i,len(self.main_rects)-1)][3]-2 if hasattr(self,'main_rects') else 10
        if self.stage_line<self.main_scroll[i]:self.main_scroll[i]=self.stage_line
        if self.stage_line>=self.main_scroll[i]+vh:self.main_scroll[i]=self.stage_line-vh+1

    def staging_key(self,key):
        item=self.selected('files')
        if key=='a':self.hunk_mode=not self.hunk_mode;return
        if key in ('<space>','d'):
            if key=='d' and not self.cfg.get('gui.skipDiscardChangeWarning',False):
                self.confirm('Discard changes','Are you sure you want to discard the selected changes?',lambda:self.apply_selected_patch(True))
