    def apply_selected_patch(self,discard=False):
        item=self.selected('files')
        if not item:return
        text=strip_ansi(self.git.diff(item,self.stage_side==1))
        lines=text.splitlines(True)
        starts=[i for i,l in enumerate(lines) if l.startswith('@@')]
        if not starts:return
        start=max([i for i in starts if i<=self.stage_line] or [starts[0]])
        end=next((i for i in starts if i>start),len(lines))
        chunk=lines[start:end]
        if not self.hunk_mode:
            chosen=self.stage_line
            rebuilt=[];oldcount=0;newcount=0
            for index,l in enumerate(chunk[1:],start+1):
                if l.startswith('\\'):continue
                if l.startswith('+'):
                    if index==chosen:rebuilt.append(l);newcount+=1
                elif l.startswith('-'):
                    if index==chosen:rebuilt.append(l);oldcount+=1
                    else:rebuilt.append(' '+l[1:]);oldcount+=1;newcount+=1
                else:rebuilt.append(l);oldcount+=1;newcount+=1
            m=re.match(r'@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)',chunk[0])
            if m:chunk=[f'@@ -{m[1]},{oldcount} +{m[2]},{newcount} @@{m[3]}\n']+rebuilt
        patch=''.join(lines[:starts[0]]+chunk)
        args=['apply','--unidiff-zero','--recount']
        if not discard:args+=['--cached']
        if self.stage_side==1 or discard:args+=['--reverse']
        result=self.execute(args,'Discard changes' if discard else ('Unstage hunk' if self.stage_side==1 else 'Stage hunk'),input=patch,record=False)
        if result.returncode and self.hunk_mode:
            self.popup=None;self.toggle_stage(item)
        self.main_scroll=[0,0];self.stage_line=0

