            else:self.error('Cannot drop the root commit')
            return
        with tempfile.TemporaryDirectory(prefix='git-ui-') as tmp:
            seq=Path(tmp)/'sequence.py';editor=Path(tmp)/'editor.py'
            seq.write_text('import sys\np=sys.argv[1]\ns=open(p).read().splitlines()\nout=[]\nfor l in s:\n parts=l.split()\n if len(parts)>1 and '+repr(ref)+'.startswith(parts[1]):\n  l='+repr(action)+'+l[l.find(" "):]\n out.append(l)\nopen(p,"w").write("\\n".join(out)+"\\n")\n')
            if message is not None:editor.write_text('import sys\nopen(sys.argv[1],"w").write('+repr(message)+')\n')
            else:editor.write_text('import sys\n')
            parent=self.git.text('rev-parse','--verify',ref+'^')
            args=['rebase','--interactive']+([parent] if parent else ['--root'])
            self.execute(args,action.capitalize()+' commit',env={'GIT_SEQUENCE_EDITOR':shlex.quote(sys.executable)+' '+shlex.quote(str(seq)),'GIT_EDITOR':shlex.quote(sys.executable)+' '+shlex.quote(str(editor))})

