    except OSError as e:return subprocess.CompletedProcess(args,1,'',str(e))


def is_repo(path):
    env=os.environ.copy();env.pop('GIT_DIR',None);env.pop('GIT_WORK_TREE',None)
    p=git_run(['rev-parse','--is-inside-work-tree'],path,env)
    return p.returncode==0 and p.stdout.strip()=='true'


def show_logs(directory):
    path=os.path.join(directory,'development.log')
    print('Tailing log file '+path+'\n',flush=True)
    at=0
    try:
        while True:
            try:
                with open(path) as f:
                    f.seek(at);txt=f.read();at=f.tell()
                    if txt:print(txt,end='',flush=True)
            except OSError:pass
            time.sleep(.25)
    except KeyboardInterrupt:return 0


def main():
    args=parse_args(sys.argv[1:])
    if args.get('version'):
        version=git_run(['--version']).stdout.strip().removeprefix('git version ') or '2.34.1'
        print(VERSION+version);return 0
    if args.get('config'):
        sys.stdout.write(resource('default-config.yml'));return 0
    directory=args.get('use-config-dir') or default_config_dir()
    if args.get('print-config-dir'):
        print(directory);return 0
    arg=args.get('git-arg','')
    if arg not in ('','status','branch','log','stash'):
        return fatal("Invalid git arg value: '"+arg+"'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.")
    cfg=Config(directory,args.get('use-config-file'),bool(args.get('use-config-dir')))
    try:cfg.load()
    except ValueError as e:return fatal(str(e))
    if args.get('logs'):return show_logs(cfg.state_directory)
    if args.get('debug'):
        level=os.environ.get('LOG_LEVEL','debug')
        try:
            os.makedirs(cfg.state_directory,exist_ok=True)
            with open(os.path.join(cfg.state_directory,'development.log'),'a') as f:f.write('time="'+time.strftime('%Y-%m-%dT%H:%M:%SZ')+'" level='+level+' msg="Starting lazygit"\n')
        except OSError:pass
    root=os.getcwd()
    if args.get('path'):
        path=args['path']
        if not os.path.isdir(path) or not (Path(path)/'.git').exists():return fatal(path+' is not a valid git repository.')
        root=os.path.abspath(path)
    elif args.get('work-tree'):
        path=args['work-tree']
        if not os.path.isdir(path):return fatal('chdir '+path+': no such file or directory')
        root=os.path.abspath(path)
    if not is_repo(root):
        mode=cfg.get('notARepository','prompt')
        if mode=='quit':sys.stderr.write('Error: must be run inside a git repository\n');return 1
        create=mode=='create'
        if mode not in ('create','skip'):
            sys.stdout.write('Not in a git repository. Create a new git repository? (y/N): ');sys.stdout.flush()
            try:answer=sys.stdin.readline().strip().lower()
            except (OSError,EOFError):answer=''
            create=answer in ('y','yes')
        if create:
            p=git_run(['init'],root)
            if p.returncode:return fatal(p.stderr.strip())
        else:
            recent=[p for p in cfg.state.get('recentrepos',[]) or [] if os.path.isdir(p) and is_repo(p)]
            if recent:root=recent[0]
            else:
                sys.stderr.write('Must open lazygit in a git repository. No valid recent repositories. Exiting.\n');return 1
    else:
        top=git_run(['rev-parse','--show-toplevel'],root).stdout.strip()
        if top:root=top
    if args.get('git-dir'):os.environ['GIT_DIR']=os.path.abspath(args['git-dir'])
    if args.get('work-tree'):os.environ['GIT_WORK_TREE']=root
    gd=git_run(['rev-parse','--absolute-git-dir'],root).stdout.strip()
    try:cfg.load_repo(root,gd or os.path.join(root,'.git'))
    except ValueError as e:return fatal(str(e))
    term=os.environ.get('TERM','')
    if not term:return terminal_error('*fmt.wrapError terminal entry not found: term not set')
    if term in ('dumb','unknown'):return terminal_error('*errors.errorString terminal not cursor addressable')
    try:
        import curses
        curses.setupterm(term=term)
    except Exception:
        return terminal_error("*fmt.wrapError couldn't open terminfo ($TERM) file for "+term+': exit status 1')
    try:
        fd=os.open('/dev/tty',os.O_RDWR);os.close(fd)
    except OSError as e:
        return terminal_error('*fs.PathError open /dev/tty: '+('no such device or address' if e.errno==errno.ENXIO else str(e.strerror).lower()))
    from interface import App
    return App(root,cfg,args).run()


if __name__=='__main__':
    try:sys.exit(main())
    except KeyboardInterrupt:sys.exit(0)
